### **2. KoboldClan.cs**
```csharp
namespace KoboldBrain.Services;

public class KoboldClan
{
    private readonly List<IKobold> _kobolds;

    public KoboldClan()
    {
        _kobolds = new List<IKobold>
        {
            new Pip(),
            new Meepo(),
            new Kib(),
            new Drak(),
            new Snip(),
            new Vex(),
            new Nubbin()
        };
    }

    public string Ask(string question)
    {
        question = question.ToLowerInvariant();

        // Naive keyword route (expand later with AI task-type detection)
        if (question.Contains("architecture")) return Get<Kib>().Respond(question);
        if (question.Contains("doc") || question.Contains("comment") || question.Contains("explain")) return Get<Meepo>().Respond(question);
        if (question.Contains("refactor") || question.Contains("clean") || question.Contains("organize")) return Get<Drak>().Respond(question);
        if (question.Contains("test")) return Get<Snip>().Respond(question);
        if (question.Contains("security") || question.Contains("perform")) return Get<Vex>().Respond(question);
        if (question.Contains("rename") || question.Contains("small change")) return Get<Nubbin>().Respond(question);

        // Default fallback
        return Get<Pip>().Respond(question);
    }

    private T Get<T>() where T : IKobold => (T)_kobolds.First(k => k is T);
}
```

